set -euo pipefail
R=/dataset/shaoshitong/search-r1-rl/cosearch
test -z "$(squeue -h --name=cosearch-local-five -o %i)"
base64 -d > "$R/tools/local-gpu.bundle" <<'BUNDLE'

BUNDLE
cd "$R/repo"
git fetch "$R/tools/local-gpu.bundle" HEAD
git merge --ff-only FETCH_HEAD
export OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 PYTHONPATH="$R/tools/test-lib:$R/repo"
"$R/env/bin/python" -m pytest tests/reproduction/test_retrieval_thread.py -q
cp reproduction/baselines/agent6-20261002/local_gpu_five.py "$R/tools/five_iteration_job_d.py"
test ! -d "$R/runs/cosearch-local-gpu-five-20261003-d"
test ! -f "$R/logs/local-five-d.queued"
tmux new-session -d -s cosearch-local-gpu-five-d-20261003 "srun --immediate=60 -p gpu -w h100-16 -N1 --ntasks=1 --gres=gpu:h100:8 --exclusive --cpus-per-task=128 --mem=768G --job-name=cosearch-local-five '$R/env/bin/python' '$R/tools/five_iteration_job_d.py' > '$R/logs/local-five-d.log' 2>&1"
touch "$R/logs/local-five-d.queued"
